css:
.gh-single-courses {
  --gh-green: #8fa78b;
  --gh-green-dark: #6f866c;
  --gh-green-pale: #e8eee5;
  --gh-cream: #faf8f1;
  --gh-cream-light: #fcfbf7;
  --gh-text: #555d59;
  --gh-line: #d8e0d4;
  color: var(--gh-text);
  font-family: "Zen Maru Gothic", "Hiragino Maru Gothic ProN", "Yu Gothic", Meiryo, sans-serif;
  font-size: 16px;
  line-height: 2;
  letter-spacing: 0.035em;
}

.gh-single-courses,
.gh-single-courses * {
  box-sizing: border-box;
}

.gh-single-courses .gh-inner {
  width: min(100%, 1080px);
  margin: 0 auto;
}

.gh-single-courses .gh-hero {
  margin-bottom: 56px;
  padding: 72px 32px;
  text-align: center;
  background: linear-gradient(135deg, var(--gh-cream-light), var(--gh-cream));
  border-top: 3px solid var(--gh-green);
  border-radius: 0 0 26px 26px;
}

.gh-single-courses .gh-eyebrow {
  margin: 0 0 12px;
  color: var(--gh-green-dark);
  font-size: 0.92rem;
  font-weight: 500;
  letter-spacing: 0.14em;
}

.gh-single-courses .gh-hero-title {
  margin: 0;
  color: var(--gh-text);
  font-size: clamp(1.8rem, 4vw, 2.65rem);
  font-weight: 500;
  line-height: 1.55;
}

.gh-single-courses .gh-hero-copy {
  max-width: 760px;
  margin: 24px auto 0;
  font-size: clamp(1rem, 2vw, 1.16rem);
}

.gh-single-courses .gh-intro {
  max-width: 880px;
  margin: 0 auto 64px;
  padding: 36px 42px;
  text-align: center;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 20px;
}

.gh-single-courses .gh-course-list {
  display: grid;
  gap: 42px;
}

.gh-single-courses .gh-course {
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 24px;
  box-shadow: 0 10px 32px rgba(85, 93, 89, 0.07);
}

.gh-single-courses .gh-course-head {
  padding: 42px 38px 36px;
  text-align: center;
  background: var(--gh-cream);
  border-bottom: 1px solid var(--gh-line);
}

.gh-single-courses .gh-course-label {
  display: inline-block;
  margin: 0 0 12px;
  padding: 4px 16px;
  color: var(--gh-green-dark);
  font-size: 0.86rem;
  background: var(--gh-green-pale);
  border-radius: 999px;
}

.gh-single-courses .gh-course-title {
  margin: 0;
  color: var(--gh-text);
  font-size: clamp(1.55rem, 3vw, 2.15rem);
  font-weight: 500;
  line-height: 1.55;
}

.gh-single-courses .gh-course-subtitle {
  margin: 12px 0 0;
  color: var(--gh-green-dark);
  font-size: clamp(1rem, 2vw, 1.14rem);
}

.gh-single-courses .gh-course-body {
  padding: 42px 42px 46px;
}

.gh-single-courses .gh-course-lead {
  max-width: 820px;
  margin: 0 auto 36px;
  text-align: center;
}

.gh-single-courses .gh-two-columns {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 24px;
  margin-bottom: 36px;
}

.gh-single-courses .gh-panel {
  padding: 28px 26px;
  background: var(--gh-cream-light);
  border: 1px solid var(--gh-line);
  border-radius: 16px;
}

.gh-single-courses .gh-panel-title {
  margin: 0 0 16px;
  padding-bottom: 10px;
  color: var(--gh-text);
  font-size: 1.15rem;
  font-weight: 500;
  border-bottom: 1px solid var(--gh-line);
}

.gh-single-courses .gh-list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.gh-single-courses .gh-list li {
  position: relative;
  margin: 0 0 9px;
  padding-left: 28px;
}

.gh-single-courses .gh-list li:last-child {
  margin-bottom: 0;
}

.gh-single-courses .gh-list li::before {
  position: absolute;
  top: 0;
  left: 2px;
  color: var(--gh-green-dark);
  font-weight: 700;
  content: "✓";
}

.gh-single-courses .gh-details {
  overflow: hidden;
  margin: 0 0 34px;
  background: #fff;
  border: 1px solid var(--gh-line);
  border-radius: 16px;
}

.gh-single-courses .gh-details-row {
  display: grid;
  grid-template-columns: 190px 1fr;
  border-bottom: 1px solid var(--gh-line);
}

.gh-single-courses .gh-details-row:last-child {
  border-bottom: 0;
}

.gh-single-courses .gh-details dt,
.gh-single-courses .gh-details dd {
  margin: 0;
  padding: 17px 21px;
}

.gh-single-courses .gh-details dt {
  font-weight: 500;
  background: var(--gh-green-pale);
}

.gh-single-courses .gh-note {
  margin: 18px 0 0;
  font-size: 0.9rem;
}

.gh-single-courses .gh-course-cta {
  padding: 30px;
  text-align: center;
  background: var(--gh-green-pale);
  border-radius: 18px;
}

.gh-single-courses .gh-course-cta p {
  margin: 0 0 18px;
}

.gh-single-courses .gh-button {
  display: inline-flex;
  min-width: 340px;
  min-height: 58px;
  padding: 12px 28px;
  align-items: center;
  justify-content: center;
  color: #fff !important;
  font-weight: 400;
  line-height: 1.5;
  text-align: center;
  text-decoration: none !important;
  background: var(--gh-green);
  border: 1px solid var(--gh-green);
  border-radius: 2px;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.gh-single-courses .gh-button:hover,
.gh-single-courses .gh-button:focus {
  color: #fff !important;
  opacity: 0.86;
  transform: translateY(-1px);
}

.gh-single-courses .gh-bottom-message {
  margin-top: 52px;
  padding: 42px 36px;
  text-align: center;
  background: var(--gh-cream);
  border-radius: 22px;
}

.gh-single-courses .gh-bottom-title {
  margin: 0 0 12px;
  color: var(--gh-text);
  font-size: clamp(1.3rem, 2.7vw, 1.8rem);
  font-weight: 500;
}

.gh-single-courses .gh-bottom-message p {
  margin: 0;
}

@media (max-width: 767px) {
  .gh-single-courses .gh-hero {
    margin-bottom: 40px;
    padding: 48px 20px;
  }

  .gh-single-courses .gh-intro {
    margin-bottom: 44px;
    padding: 28px 22px;
    text-align: left;
  }

  .gh-single-courses .gh-course-list {
    gap: 30px;
  }

  .gh-single-courses .gh-course-head {
    padding: 34px 22px 30px;
  }

  .gh-single-courses .gh-course-body {
    padding: 30px 20px 34px;
  }

  .gh-single-courses .gh-course-lead {
    text-align: left;
  }

  .gh-single-courses .gh-two-columns {
    grid-template-columns: 1fr;
  }

  .gh-single-courses .gh-details-row {
    grid-template-columns: 1fr;
  }

  .gh-single-courses .gh-details dt {
    padding-bottom: 8px;
  }

  .gh-single-courses .gh-details dd {
    padding-top: 8px;
  }

  .gh-single-courses .gh-course-cta,
  .gh-single-courses .gh-bottom-message {
    padding: 28px 20px;
  }

  .gh-single-courses .gh-button {
    width: 100%;
    min-width: 0;
  }
}
